return ['domain'=>'tranzly','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T07:20:29+00:00','po-revision-date'=>'2026-09-26T07:20:29+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','The foundation release of the rebuilt Tranzly: a list of your site\'s languages, a language switcher block, and the language API other plugins read.'=>'Temeljno izdanje ponovno izgrađenog Tranzlyja: popis jezika vaše web-lokacije, blok za prebacivanje jezika i jezični API koji drugi dodaci čitaju.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'AI pružatelji usluga','The makers of ChatGPT. A good all-rounder.'=>'Tvorci sustava ChatGPT. Dobar svestrani alat.','The makers of Claude. Strong at writing and careful reasoning.'=>'Tvorci modela Claude. Snažan u pisanju i opreznom zaključivanju.','Google\'s Gemini models. Fast and inexpensive.'=>'Gemini modeli tvrtke Google. Brzo i povoljno.','A European AI company with fast, inexpensive models.'=>'Europska AI tvrtka s brzim i povoljnim modelima.','Low-cost models that are good at writing and code.'=>'Jeftini modeli koji su dobri u pisanju i pisanju koda.','One key for models from many different providers.'=>'Jedan ključ za modele od mnogo različitih pružatelja usluga.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Bilo koja usluga koja radi poput OpenAI-jeva API-ja, uključujući model koji se izvodi na vašem vlastitom računalu ili poslužitelju.','General (used when nothing more specific is set)'=>'Općenito (koristi se kada nije postavljeno ništa specifičnije)','Writing and rewriting'=>'Pisanje i prepisivanje','Translation'=>'Prijevod','Code and CSS'=>'Kod i CSS','Sorry, you are not allowed to access this page.'=>'Žao nam je, nemate dopuštenje za pristup ovoj stranici.','These settings are shared by every plugin that uses them: %s.'=>'Ove postavke dijele svi dodaci koji ih koriste: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Vaši su ključevi šifrirani u bazi podataka ove stranice i šalju se samo davatelju usluga kojeg ste odabrali – nikada nama.','Step 1 of 2: choose an AI provider'=>'1. korak od 2: odaberite AI davatelja usluge','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Donosite vlastiti ključ, tako da pružatelju usluga plaćate izravno za ono što koristite. Niste sigurni? Bilo koja od ovih opcija dobro funkcionira; kasnije možete dodati još.','Next'=>'Sljedeće','Step 2 of 2: connect %s'=>'Korak 2 od 2: povežite %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Unesite adresu svoje usluge kompatibilne s OpenAI koja završava s /v1. Ključ je potreban samo ako ga usluga zatraži.','Open %s and sign in (or create a free account).'=>'Otvorite %s i prijavite se (ili izradite besplatan račun).','the %s API keys page'=>'%s stranica API ključeva','Create a new key and copy it.'=>'Izradite novi ključ i kopirajte ga.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Zalijepite ga ispod i pritisnite „Spremi i testiraj”. Šaljemo jedan mali zahtjev kako bismo provjerili radi li.','Most providers need a little credit on the account before a key works: %s.'=>'Većina pružatelja usluga treba malo kredita na računu prije nego što ključ počne raditi: %s.','add credit'=>'dodaj kredit','← Choose a different provider'=>'← Odaberite drugog pružatelja usluga','Address'=>'Adresa','Saved key ends in …%s — paste a new one to replace it'=>'Spremljeni ključ završava s …%s — zalijepite novi da biste ga zamijenili','Key (optional)'=>'Ključ (neobavezno)','API key'=>'API ključ','Save and test'=>'Spremi i testiraj','Providers'=>'Pružatelji usluga','Provider'=>'Pružatelj usluga','Status'=>'Status','Key'=>'Ključ','Get a key'=>'Nabavite ključ','Test'=>'Test','Remove'=>'Ukloni','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Spremljeno novijom verzijom dodatka: ažurirajte ovaj dodatak ili ponovno unesite ključ.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Spremljeni ključ se više ne može otvoriti (sigurnosni ključevi web-mjesta su promijenjeni). Unesite ga ponovno.','Not connected'=>'Nije spojeno','Connected — last test passed %s'=>'Povezano — posljednji test je prošao %s','Last test failed: %s'=>'Posljednji test nije uspio: %s','Connected — not tested yet'=>'Povezano — još nije testirano','Which model to use'=>'Koji model koristiti','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ označava našu preporuku za taj zadatak. Popis uključuje svaki model koji vaš ključ može koristiti, učitan uživo od pružatelja usluge.','— Recommended for the provider —'=>'— Preporučuje se za pružatelja usluga —','Save models'=>'Spremi modele','Refresh the model lists from the providers'=>'Osvježite liste modela od pružatelja usluga','best quality'=>'najbolja kvaliteta','lowest cost'=>'najniža cijena','fastest'=>'najbrže','Add a model yourself'=>'Dodajte model sami','A model came out today? Paste its exact name to use it straight away.'=>'Danas je izašao novi model? Zalijepite njegov točan naziv kako biste ga odmah počeli koristiti.','Model name'=>'Naziv modela','Add model'=>'Dodaj model','Recommended models list'=>'Popis preporučenih modela','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Lista preporučenih modela nije mogla biti potvrđena, stoga se preporuke ne prikazuju. Ponovno instalirajte dodatak ili uključite dnevna ažuriranja u nastavku.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Korišteni popis objavljen je %s. Svako ažuriranje dodatka donosi novi.','Also check Zinn Digital® once a day for an updated list.'=>'Također provjerite Zinn Digital® jednom dnevno za ažurirani popis.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Šalje se samo običan zahtjev za preuzimanje: bez ključa, bez adrese web-mjesta, ništa o vašem sadržaju. Popis je potpisan, a popis koji ne prođe provjeru potpisa se zanemaruje.','Last checked %1$s: %2$s.'=>'Zadnja provjera %1$s: %2$s.','Save, and check now if turned on'=>'Spremite i provjerite odmah ako je uključeno','a newer list was installed'=>'instaliran je noviji popis','already up to date'=>'već ažurirano','the download failed the signature check and was ignored'=>'preuzimanje nije prošlo provjeru potpisa i zanemareno je','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® nije dostupan; trenutačni popis ostaje u upotrebi','turned off'=>'isključeno','Open'=>'Otvori','Check their status page'=>'Provjerite njihovu stranicu sa statusom','Open your billing page'=>'Otvorite svoju stranicu za naplatu','Open your API keys page'=>'Otvorite stranicu s API ključevima','Open the AI settings'=>'Otvorite postavke umjetne inteligencije','Sorry, you are not allowed to do that.'=>'Žao nam je, nemate dopuštenje za to.','Unknown provider.'=>'Nepoznati davatelj.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Unesite adresu svoje usluge, na primjer http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'To ne izgleda kao API ključ. Kopirajte ga ponovno, bez razmaka.','Paste your API key first.'=>'Prvo zalijepite svoj API ključ.','Key removed.'=>'Ključ je uklonjen.','Models saved.'=>'Modeli su spremljeni.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Unesite točan naziv modela, na primjer onako kako je navedeno u dokumentaciji pružatelja usluge.','Added %s. Choose it under "Which model to use".'=>'Dodan %s. Odaberite ga pod "Koji model koristiti".','Model removed.'=>'Model je uklonjen.','Daily updates are off. The list that came with the plugin is used.'=>'Dnevna ažuriranja su isključena. Koristi se popis koji je došao s dodacima.','Checked: %s.'=>'Odabrano: %s.','Model lists refreshed.'=>'Popisi modela su osvježeni.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Vaš AI ključ je spremila novija verzija jednog od vaših dodataka. Ažurirajte ovaj dodatak ili ponovno unesite ključ u postavkama za AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Vaš spremljeni AI ključ se više ne može otvoriti (sigurnosni ključevi web-mjesta su promijenjeni). Unesite ga ponovno u postavkama umjetne inteligencije.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI još nije podešen. Dodajte ključ za AI davatelja usluga u AI postavkama.','No model is chosen for this task. Pick one in the AI settings.'=>'Ni jedan model nije odabran za ovaj zadatak. Odaberite jedan u postavkama umjetne inteligencije.','That AI provider is not supported by this version of the plugin.'=>'Taj pružatelj usluga umjetne inteligencije nije podržan u ovoj verziji dodatka.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Ova stranica ne može dosegnuti vašu AI uslugu. Provjerite radi li i je li njena adresa dostupna s vašeg web poslužitelja (usluga na vašem vlastitom računalu nije dostupna s hostirane stranice).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Ova stranica nije mogla dosegnuti %s. Provjerite njihovu stranicu statusa; ako rade, vaš poslužitelj možda blokira odlazne veze ili je adresa pogrešna.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s navodi da vaš račun nema preostalog kredita ili kvote. Dodajte kredit ili povećajte ograničenje na svom računu kod njih, a zatim pokušajte ponovo.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s nije prihvatio vaš ključ. Možda je pogrešno upisan, opozvan ili je istekao. Izradite novi ključ i zalijepite ga ovdje.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s je odbio ovaj zahtjev za vaš ključ. Ključ možda nema pristup ovom modelu ili značajci, ili je vaš račun potrebno verificirati.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model "%1$s" nije dostupan od davatelja %2$s za vaš ključ. Odaberite drugi model u postavkama umjetne inteligencije.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ograničava brzinu kojom vaš ključ može slati zahtjeve. Pričekajte minutu i pokušajte ponovno ili povećajte ograničenje brzine kod njih.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s trenutačno ima problema (prekid rada ili preopterećenje s njihove strane). S vašim postavkama je sve u redu. Pokušajte ponovno uskoro.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Zahtjev za AI nije uspio iz razloga koji nismo mogli utvrditi. Pokušajte ponovno; ako se to nastavi događati, obratite se podršci s detaljima u nastavku.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Pružatelj usluga umjetne inteligencije odgovorio je u obliku koji ovaj dodatak nije mogao pročitati. Pokušajte ponovno; ako se to nastavi događati, odaberite drugi model ili se obratite podršci.','Custom (OpenAI-compatible)'=>'Prilagođeno (kompatibilno s OpenAI)','Save a key for this provider first.'=>'Prvo spremite ključ za ovog pružatelja usluga.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Vaš ključ radi, ali pružatelj usluge za njega ne navodi nijedan tekstualni model. Dodajte model sami u nastavku.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Povezano. %1$s je odgovorio/la koristeći %2$s. Vaše AI značajke spremne su za upotrebu.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Vaša korisnička uloga ne smije koristiti umjetnu inteligenciju na ovoj stranici. Obratite se administratoru.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ova je stranica dosegla svoju mjesečnu potrošnju na umjetnu inteligenciju. Administrator ju može povećati u postavkama umjetne inteligencije.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Ova je stranica dosegnula mjesečni limit AI zahtjeva. Administrator ga može povećati u postavkama za AI.','Usage and cost'=>'Upotreba i troškovi','The log, limits and role permissions apply to AI used through: %s.'=>'Dnevnik, ograničenja i dozvole uloga primjenjuju se na AI koji se koristi putem: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Troškovi su približni, izračunati na temelju objavljenih cijena; model bez poznate cijene računa se kao nula.','This month: %1$s requests, about %2$s.'=>'Ovaj mjesec: %1$s zahtjeva, oko %2$s.','When'=>'Kada','Who'=>'Tko','Used for'=>'Upotrebljava se za','Model'=>'Model','Tokens in / out'=>'Tokeni / izlazni tokeni','About'=>'O programu','Result'=>'Rezultat','No AI requests have been made yet.'=>'Još nije podnesen nijedan zahtjev za AI.','Done'=>'Gotovo','Limits and permissions'=>'Ograničenja i dozvole','Monthly spending limit (US dollars)'=>'Mjesečni limit potrošnje (US dolara)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Ostavite prazno za bez ograničenja. AI se zaustavlja do kraja mjeseca kada približni trošak dosegne tu vrijednost.','Monthly request limit'=>'Mjesečno ograničenje zahtjeva','Leave empty for no limit.'=>'Ostavite prazno za bez ograničenja.','Who may use AI'=>'Tko može koristiti AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Označite ništa kako biste omogućili svima koji mogu koristiti značajke dodatka da koriste umjetnu inteligenciju. Administratori je uvijek mogu koristiti.','Save limits and permissions'=>'Spremi ograničenja i dozvole','Limits and permissions saved.'=>'Ograničenja i dozvole su spremljeni.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skripte administratorskog zaslona nedostaju u ovoj kopiji dodatka. Ponovno ga instalirajte iz objavljenog paketa.','This screen needs JavaScript.'=>'Ovaj zaslon zahtijeva JavaScript.','Choose a language'=>'Odaberite jezik','Upgrade'=>'Nadogradite','Pricing'=>'Cijene','Start Trial'=>'Započni probno razdoblje','Account'=>'Korisnički račun','Contact Us'=>'Kontaktirajte nas','Affiliation'=>'Pripadnost','the kind of softwarePlugin'=>'Dodatak','greetingHey %s,'=>'Pozdrav %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Prijavite se kako biste primali obavijesti e-poštom o sigurnosnim i značajnim ažuriranjima, edukativnom sadržaju i povremenim ponudama te kako biste podijelili neke osnovne informacije o WordPress okruženju. To će nam pomoći da učinimo %s kompatibilnijim s vašom web-lokacijom i boljim u obavljanju onoga što vam je potrebno.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Prijavite se za primanje obavijesti e-poštom o sigurnosnim ažuriranjima i značajkama, edukativnom sadržaju i povremenim ponudama te za dijeljenje osnovnih informacija o WordPress okruženju.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Ako ovo preskočite, nema problema! %1$s će i dalje raditi ispravno.','Allow & Continue'=>'Dopusti i nastavi','verbSkip'=>'Preskoči','Skipping, please wait'=>'Preskače se, molimo pričekajte','Continue'=>'Nastavi','Please wait'=>'Molimo pričekajte','as activating pluginActivating'=>'Aktiviranje','This will allow %s to'=>'Ovo će omogućiti %s da','Privacy Policy'=>'Pravila o privatnosti','Terms of Service'=>'Uvjeti korištenja','License Agreement'=>'Licencni ugovor','Have a license key?'=>'Imate li licencni ključ?','Activate License'=>'Aktiviraj licencu','View Basic Profile Info'=>'Pregledaj osnovne informacije profila','Your WordPress user\'s: first & last name, and email address'=>'Podaci vašeg WordPress korisnika: ime i prezimen te adresa e-pošte','View Basic Website Info'=>'Pogledajte osnovne informacije o web-mjestu','Homepage URL & title, WP & PHP versions, and site language'=>'URL i naslov početne stranice, verzije WP-a i PHP-a te jezik web-mjesta','View Basic %s Info'=>'Pregledajte osnovne podatke za %s','Current %s & SDK versions, and if active or uninstalled'=>'Trenutne %s & SDK verzije te jesu li aktivne ili deinstalirane','Newsletter'=>'Bilten','Updates, announcements, marketing, no spam'=>'Ažuriranja, obavijesti, marketing, bez neželjene pošte','View Diagnostic Info'=>'Prikaz dijagnostičkih podataka','WordPress & PHP versions, site language & title'=>'WordPress i PHP verzije, jezik i naziv web-mjesta','View Plugins & Themes List'=>'Pregledajte popis dodataka i tema','Names, slugs, versions, and if active or not'=>'Imena, kratki nazivi (slugs), verzije te jesu li aktivni ili ne','optional'=>'neobavezno','Never miss an important update'=>'Nikada ne propustite važnu obavijest','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Uveli smo ovu mogućnost dobrovoljne prijave kako nikada ne biste propustili važno ažuriranje i kako biste nam pomogli da %s učinimo kompatibilnijim s vašom web-lokacijom i boljim u ispunjavanju vaših potreba.','Thank you for updating to %1$s v%2$s!'=>'Hvala vam što ste ažurirali na %1$s v%2$s!','That language is not one of this site\'s languages.'=>'Taj jezik nije jedan od jezika ove stranice.','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Prefiks se mora sastojati od 1 do 8 malih slova ili znamenki, počinjati slovom i ne smije sadržavati naziv dodatka.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" nije jezični kod. Upotrijebite WordPress lokalitet kao što je fr_FR ili de_DE.','List at least one language.'=>'Navedite barem jedan jezik.','That is more languages than one site can list.'=>'To je više jezika nego što jedna stranica može prikazati.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Izradio Neil Lock, izvršni direktor tvrtke Zinn Digital® Ltd','Version %s'=>'Verzija %s','Tranzly website'=>'Tranzly web-stranica','Zinn Digital® website'=>'Web-mjesto za Zinn Digital®','Settings saved.'=>'Postavke su spremljene.','See the Pro plans and pricing'=>'Pogledajte Pro planove i cijene','Languages'=>'Jezici','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Prvi jezik je onaj na kojem je vaš sadržaj napisan. Posjetitelji se prebacuju pomoću bloka za prebacivanje jezika.','(default)'=>'(zadano)','Locale code'=>'Jezični kod','For example fr_FR'=>'Na primjer fr_FR','Name (optional)'=>'Naziv (nije obavezno)','For example Français'=>'Na primjer Français','Add language'=>'Dodaj jezik','Front-end output'=>'Izlaz sučelja','Class name prefix'=>'Prefiks naziva klase','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Svaki naziv klase koji dodatak ispisuje na vašim stranicama počinje s ovim prefiksom, tako da stranice ne otkrivaju koji ih je dodatak izradio. 1 do 8 malih slova ili znamenaka, s početnim slovom.','Beta updates'=>'Beta ažuriranja','This site receives beta versions as updates.'=>'Ova stranica prima beta verzije kao ažuriranja.','This site receives stable versions only.'=>'Ova stranica prima samo stabilne verzije.','Change this on the Account page'=>'Promijenite ovo na stranici Račun','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Beta verzije nude se licenciranim Pro instalacijama koje su povezane s njihovim računom. Nakon što se povežete, možete se pridružiti sa stranice Račun.','Save settings'=>'Spremi postavke','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Dodajte drugi jezik pod opcijom Tranzly u administrativnom izborniku i preklopnik će se pojaviti ovdje.','Switcher'=>'Preklopnik','Accessible label'=>'Pristupačna oznaka','block titleLanguage switcher'=>'Jezični preklopnik','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Poveznice na ovu stranicu na svim jezicima web-mjesta. Ne prikazuje se ništa dok nisu navedena dva ili više jezika.','block keywordlanguage'=>'Jezik','block keywordswitcher'=>'prebacivač','block keywordtranslation'=>'prijevod']];